{
  "id": "ComposeRecipient",
  "choices": [
    {
      "type": "string",
      "description": "A name and email address in mailbox format (<var>Name <email@example.com></var>), or just an email address. Mailing lists are specified as <var>ListName <ListName></var>. Use $(ref:messengerUtilities.parseMailboxString) to extract the name and/or the email from the mailbox string, or to expand mailing list entries."
    },
    {
      "type": "object",
      "properties": {
        "id": {
          "type": "string",
          "max_manifest_version": 2,
          "description": "The ID of a contact or mailing list from the $(doc:contacts) or $(doc:mailingLists)."
        },
        "nodeId": {
          "type": "string",
          "min_manifest_version": 3,
          "description": "The ID of a contact or mailing list node from the $(doc:addressBooks.contacts) or $(doc:addressBooks.mailingLists)."
        },
        "type": {
          "type": "string",
          "description": "Which sort of object this ID is for.",
          "enum": ["contact", "mailingList"]
        }
      }
    }
